mapper.select:
SELECT COUNT(1) AS totalReplyCount, COUNT(IF(read_status != #{status}, 1, 0)) AS unreadReplyCount, AVG(DATEDIFF(teacher_reply_time, parent_reply_time)) AS avgReplyDuration, ROUND(COUNT(IF(teacher_reply_time IS NOT NULL, 1, 0)) / COUNT(1), 2) AS replyFinishRate FROM parent_reply WHERE deleted = 0
AND create_time between #{startTime} AND #{endTime}
GROUP BY DATE(create_time)

SELECT `name` AS `name`, COUNT(1) AS count FROM parent_reply AS r LEFT JOIN student_info AS s ON s.id = r.student_id WHERE r.deleted = 0
AND r.create_time between #{startTime} AND #{endTime}
GROUP BY student_id

SELECT class_name AS `name`, COUNT(1) AS count FROM parent_reply AS r JOIN student_info AS s ON s.id = r.student_id

    AND r.create_time between #{startTime} AND #{endTime}

GROUP BY class_name

SELECT DATE_FORMAT(parent_reply_time, '%Y-%m-%d') AS date, COUNT(1) AS count FROM parent_reply WHERE deleted = 0
AND parent_reply_time between #{startTime} AND #{endTime}
GROUP BY `date` ORDER BY `date`
